from lib import *
S = SS('l26')
steps = [
    step("git init --ref-format=reftable 的仓库:.git/HEAD 是占位值 ref: refs/heads/.invalid(git 自己不读它),配置里多了 extensions.refstorage=reftable,并且 core.repositoryformatversion 变成 1;.git/refs/heads 不再是目录,而是一个 41 字节的文件,内容是 “this repository uses the reftable format”,防止旧版本的 git 误把它当成 files 后端的仓库;真正的引用在 .git/reftable/ 里:一个 124 字节的表文件和记录表清单的 tables.list(43 字节)。git symbolic-ref HEAD 仍然正常得到 refs/heads/main。", t=tl(S(1)), mark=lidx(S(1), 'ref: refs/heads/.invalid', 'this repository uses the reftable format', 'extensions.refstorage=reftable'), done=lidx(S(1), '124 0x0000', 'tables.list', 'refs/heads/main'), kv=KV([['HEAD', '占位值 .invalid'], ['refs/heads', '一个说明文件,不是目录'], ['引用在哪', '.git/reftable/*.ref'], ['版本', 'repositoryformatversion = 1']], ['refs/heads'])),
    step("每次更新 ref 都往 reftable/ 里加一个新表,文件名是“起始更新序号-结束更新序号-校验”。连续做 git branch b2 … b8:b2 之后只有 1 个表(序号 1~3,355 字节)——新表和旧表立刻合并;b5 之后出现了 2 个表(1~5 和 6~6);b6 之后又合并成 1 个(1~7,481 字节)。更新序号每次加 1,表的数量在 1 到 2 之间波动,没有堆积。", t=tl(S(2)), mark=lidx(S(2), 'git branch b5 之后', 'git branch b7 之后'), done=lidx(S(2), 'git branch b2 之后', 'git branch b6 之后', 'git branch b8 之后'), b=bars([['b2 之后', 1, '1 个表'], ['b5 之后', 2, '2 个表'], ['b6 之后', 1, '1 个表'], ['b7 之后', 2, '2 个表'], ['b8 之后', 1, '1 个表']], 2, mark=[1, 3], done=[0, 2, 4]), kv=KV([['写一次', '一个新表,序号 +1'], ['自动合并', '大小相近的相邻表合并'], ['表的数量', '很少,不会像松散文件那样堆积']], ['自动合并'])),
    step("解析合并后的表(543 字节):头部 24 字节:魔数 REFT、版本 1、块大小 4096、最小更新序号 1、最大更新序号 9;尾部是最后 68 字节:先重复头部的 24 字节(与头部相同:True),再是 5 个 8 字节偏移(ref_index_offset=0、obj_offset=0、obj_index_offset=0、log_offset=266、log_index_offset=0),最后 4 字节 CRC-32 e12b8a26,对尾部前 64 字节重新计算,一致。偏移为 0 的部分(索引、对象反查)在这么小的表里没有;log_offset=266 说明 reflog 也存在同一个表文件里。git for-each-ref 数出 8 个 ref。", t=tl(S(3)), mark=lidx(S(3), '头部:魔数', '尾部(最后 68 字节)', 'CRC-32'), done=lidx(S(3), '0000  52 45 46 54', '表里有多少个 ref'), kv=KV([['头部', 'REFT + 版本 + 块大小 + 更新序号范围'], ['尾部', '头部副本 + 各区偏移 + CRC-32'], ['reflog', '同样存在表里(log_offset)']], ['尾部'])),
    step("5000 个 tag 的三种存放(占用字节是文件大小之和,不含文件系统块的浪费):files 松散:5001 个文件、205,041 字节,git tag -l 91.1 ms;files 打包成 packed-refs:1 个文件、290,103 字节,14.6 ms;reftable:1 个表、135,479 字节,14.8 ms。reftable 比 packed-refs 小一半(同前缀的 ref 名做了前缀压缩),列举速度与 packed-refs 一样;查单个 ref 三者都是约 11 ms,没有差别。", t=tl(S(4)), mark=lidx(S(4), 'reftable  ', 'files(packed-refs)'), done=lidx(S(4), 'files(松散)'), b=bars([['松散:git tag -l', 91.1, '91.1 ms'], ['packed-refs:git tag -l', 14.6, '14.6 ms'], ['reftable:git tag -l', 14.8, '14.8 ms']], 91.1, mark=[2], done=[0, 1]), kv=KV([['松散', '5001 个文件'], ['packed-refs', '290,103 字节'], ['reftable', '135,479 字节,前缀压缩'], ['单个查找', '三者无差别']], ['reftable'])),
    step("一次 git update-ref --stdin 事务创建 5000 个 tag,只产生 1 个表。而逐个执行 git tag(200 次)则每次写一个小表,靠自动合并保持表数量很少:第 1 个后 2 个表,第 3 个后 1 个,第 100 个后 3 个,第 200 个后 4 个——表的数量大致与次数的对数成正比,而不是 200。事务写入是原子的:一次事务的所有更新在同一个更新序号里。", t=tl(S(5)), mark=lidx(S(5), '逐个 git tag'), done=lidx(S(5), '表的个数 = 1'), b=bars([['事务写 5000 个', 1, '1 个表'], ['逐个 git tag 200 次', 4, '4 个表']], 4, mark=[1], done=[0]), kv=KV([['一次事务', '一个表,一个更新序号'], ['逐个更新', '每次一个小表,持续合并'], ['200 次之后', '只有 4 个表']], ['逐个更新'])),
    step("git refs migrate 在两种后端间转换:--ref-format=reftable 之后 HEAD 变成占位值、出现 reftable/ 目录、没有 logs/ 和 packed-refs,git for-each-ref 仍列出 refs/heads/b1、refs/heads/main、refs/tags/t1,配置里 repositoryformatversion=1、refstorage=reftable;迁回 --ref-format=files:HEAD 恢复为 ref: refs/heads/main,出现 logs/ 和 packed-refs(ref 被打包存放),refstorage 配置消失,repositoryformatversion=0。同一份 ref 内容,两种后端都能读出。", t=tl(S(6)), mark=lidx(S(6), '--ref-format=files', 'core.repositoryformatversion=0'), done=lidx(S(6), '--ref-format=reftable', 'extensions.refstorage=reftable', 'refs/tags/t1'), kv=KV([['migrate', '双向转换,ref 与 reflog 保留'], ['reftable', '没有 logs/、packed-refs'], ['files', '有 logs/、packed-refs']], ['migrate'])),
]
A = mkarti('l26', 26, 'Git,reftable,refs,ref-format,真实验证,动画演示',
    '在真实 git 2.54.0 里创建 reftable 仓库并解析它:HEAD 占位值、refs/heads 说明文件、.git/reftable 下按更新序号命名的表文件与 tables.list;解析表的 24 字节头、68 字节尾与 CRC-32;5000 个 tag 的 reftable 为 135,479 字节(packed-refs 为 290,103),列举与 packed-refs 一样快;事务写入只产生 1 个表,git refs migrate 可在两种后端间转换。',
    'reftable 是 git 新的引用存储格式:不再一个 ref 一个文件,而是一组有序的表。这篇创建 reftable 仓库,看目录结构、每次更新产生的表文件与自动合并、表的头尾字节、5000 个 tag 时的体积和耗时,以及与 files 后端互相迁移。',
    [('135,479 vs 290,103', '5000 个 tag:reftable 与 packed-refs 的字节数'), ('1 个表', '一次事务写入 5000 个 ref 产生的表数量;逐个更新 200 次后也只有 4 个表'), ('68 字节', 'reftable 表文件尾部的长度,含 CRC-32,可以逐字节校验')],
    [('目录结构', '<p>reftable 仓库的 <code>.git/HEAD</code> 是占位值 <code>ref: refs/heads/.invalid</code>,<code>.git/refs/heads</code> 是一个说明文件而不是目录——用来挡住不认识 reftable 的旧版 git。配置里 <code>extensions.refstorage=reftable</code>,版本升到 1。真正的 ref(和 reflog)存在 <code>.git/reftable/</code> 下。</p>'),
     ('追加与合并', '<p>每次更新写一个新表,文件名里是它覆盖的更新序号范围。git 自动把相邻、大小相近的表合并,所以表的数量保持很小,不像松散 ref 那样随 ref 数线性增加文件。</p>'),
     ('表的字节', '<p>表以 24 字节头开头:魔数 <code>REFT</code>、版本、块大小、最小与最大更新序号;末尾 68 字节是头的副本加各区偏移(ref 索引、对象反查、reflog 等)与 CRC-32。小表里没有的区域偏移为 0;reflog 也存在表里。</p>'),
     ('体积与速度', '<p>5000 个 tag 时,reftable 只有 packed-refs 的一半左右(ref 名前缀压缩);列举所有 ref 与 packed-refs 一样快,远快于松散文件;只查一个 ref 三者没有差别。</p>'),
     ('原子写入', '<p>一次事务里的所有更新属于同一个更新序号,只写一个表;逐个更新则产生许多小表,靠合并控制数量(200 次后只有 4 个)。</p>'),
     ('迁移', '<p><code>git refs migrate --ref-format=reftable|files</code> 在两种后端之间转换,ref 内容保持不变。reftable 没有 <code>logs/</code> 与 <code>packed-refs</code>,迁回 files 后它们重新出现。</p>')],
    steps,
    [ENV_I_GIT + '。表文件头尾按字节解析(解析器在实验脚本内),CRC-32 校验通过;“占用字节”是文件大小之和,不含文件系统块对齐;5000 个 tag 用 git update-ref --stdin 创建;耗时 5 次中位数',
     '没有验证:表内部的 ref 块 / 对象块 / reflog 块的记录编码(前缀压缩、变长整数),只解析了头尾;多个并发写入者之间的锁(tables.list.lock);在没有 reftable 支持的 git 版本上打开这样的仓库的表现(只看到了 refs/heads 说明文件);reftable 的 reflog 过期;更大规模(十万以上 ref)的性能'],
    'reftable')
